/**
 * A single naming-convention violation reported by the linter.
 */
export interface LintViolation {
    /** Identifier of the rule that was violated. */
    rule: string;
    /** Human readable description of the violation. */
    message: string;
    /** The offending name (declaration, property or enum constant). */
    name: string;
    /** JSON path (into the AST) pointing at the offending name. */
    path: Array<string | number>;
}

/** Rule identifiers used when reporting violations. */
const RULES = {
    DECLARATION_CAMEL_CASE: 'type-declaration-camel-case',
    PROPERTY_PASCAL_CASE: 'property-pascal-case',
    ENUM_CONSTANT_UPPER_SNAKE_CASE: 'enum-constant-upper-snake-case',
} as const;

/**
 * Returns the short class name (the part after the final '.') for a fully
 * qualified metamodel `$class` value, e.g.
 * `concerto.metamodel@1.0.0.ConceptDeclaration` -> `ConceptDeclaration`.
 */
function getShortClassName($class: unknown): string {
    if (typeof $class !== 'string') {
        return '';
    }
    const index = $class.lastIndexOf('.');
    return index === -1 ? $class : $class.substring(index + 1);
}

/**
 * A name begins with an uppercase letter (e.g. PascalCase or UPPER_SNAKE_CASE).
 */
function startsWithUppercase(name: string): boolean {
    return /^[A-Z]/.test(name);
}

/**
 * A name is in UPPER_SNAKE_CASE, e.g. `RED`, `LIGHT_BLUE`, `LEVEL_1`.
 */
function isUpperSnakeCase(name: string): boolean {
    return /^[A-Z][A-Z0-9]*(_[A-Z0-9]+)*$/.test(name);
}

/**
 * Determines whether a declaration is an enum declaration, whose properties
 * are enum constants (rather than fields).
 */
function isEnumDeclaration(declaration: any): boolean {
    return getShortClassName(declaration?.$class) === 'EnumDeclaration';
}

/**
 * Lints the declarations of a single Concerto model AST, appending any
 * naming-convention violations to `violations`.
 */
function lintModel(model: any, violations: Array<LintViolation>): void {
    const declarations: Array<any> = Array.isArray(model?.declarations)
        ? model.declarations
        : [];

    declarations.forEach((declaration, declarationIndex) => {
        const declarationName: unknown = declaration?.name;

        // Rule: type declarations must use camelCase (must not start uppercase).
        if (typeof declarationName === 'string' && startsWithUppercase(declarationName)) {
            violations.push({
                rule: RULES.DECLARATION_CAMEL_CASE,
                message: `Type declaration "${declarationName}" should be camelCase and must not begin with an uppercase letter.`,
                name: declarationName,
                path: ['declarations', declarationIndex, 'name'],
            });
        }

        const properties: Array<any> = Array.isArray(declaration?.properties)
            ? declaration.properties
            : [];
        const enumDeclaration = isEnumDeclaration(declaration);

        properties.forEach((property, propertyIndex) => {
            const propertyName: unknown = property?.name;
            if (typeof propertyName !== 'string') {
                return;
            }
            const path: Array<string | number> = [
                'declarations',
                declarationIndex,
                'properties',
                propertyIndex,
                'name',
            ];

            if (enumDeclaration) {
                // Rule: enum constants must use UPPER_SNAKE_CASE.
                if (!isUpperSnakeCase(propertyName)) {
                    violations.push({
                        rule: RULES.ENUM_CONSTANT_UPPER_SNAKE_CASE,
                        message: `Enum constant "${propertyName}" should be UPPER_SNAKE_CASE.`,
                        name: propertyName,
                        path,
                    });
                }
            } else {
                // Rule: properties must use PascalCase (must start uppercase).
                if (!startsWithUppercase(propertyName)) {
                    violations.push({
                        rule: RULES.PROPERTY_PASCAL_CASE,
                        message: `Property "${propertyName}" should be PascalCase and must begin with an uppercase letter.`,
                        name: propertyName,
                        path,
                    });
                }
            }
        });
    });
}

/**
 * Lints a JSON-serialized Concerto model AST, enforcing naming conventions
 * for type declarations, properties and enum constants.
 *
 * Rules enforced:
 * - Type declarations (concept, asset, participant, transaction, event, enum,
 *   scalar) must use camelCase (must not begin with an uppercase letter).
 * - Properties (fields) of non-enum types must use PascalCase (must begin with
 *   an uppercase letter).
 * - Enum constants must use UPPER_SNAKE_CASE.
 *
 * @param ast - a JSON-serialized Concerto model AST string.
 * @returns a Promise resolving to an array of lint violation objects; an empty
 * array is returned when no naming violations are detected.
 */
export async function lintAST(ast: string): Promise<Array<any>> {
    const violations: Array<LintViolation> = [];

    const parsed = JSON.parse(ast);

    // Support a single model AST, or a container of multiple models.
    const models: Array<any> = Array.isArray(parsed?.models)
        ? parsed.models
        : [parsed];

    models.forEach((model) => lintModel(model, violations));

    return violations;
}
